struct Nargs
    {
        const size_t min;
        const size_t max;
        Nargs(size_t min_, size_t max_);
        Nargs(size_t num_);
        friend bool operator == (const Nargs &lhs, const Nargs &rhs);
        friend bool operator != (const Nargs &lhs, const Nargs &rhs);
