            Command(Group &base_, std::string name_, std::string help_, std::function<void(Subparser&)> coroutine_ = {});
            const std::string &ProglinePostfix() const; void ProglinePostfix(const std::string &);
            const std::string &Description() const; void Description(const std::string &);
            const std::string &Epilog() const; void Epilog(const std::string &);
            const std::string &Name() const; const std::string &Help() const;
            void RequireCommand(bool value);
            virtual bool IsGroup() const override; virtual bool Matched() const noexcept override; operator bool() const noexcept; void Match() noexcept; void SelectCommand(Command *c) noexcept;
            virtual FlagBase *Match(const EitherFlag &flag) override; virtual std::vector<FlagBase*> GetAllFlags() override; virtual PositionalBase *GetNextPositional() override; virtual bool HasFlag() const override; virtual bool HasPositional() const override; virtual bool HasCommand() const override;
            std::vector<std::string> GetCommandProgramLine(const HelpParams &params) const; virtual std::vector<std::string> GetProgramLine(const HelpParams &params) const override; virtual std::vector<Command*> GetCommands() override; virtual std::vector<std::tuple<std::string, std::string, unsigned>> GetDescription(const HelpParams &params, const unsigned int indent) const override; virtual void Validate(const std::string &shortprefix, const std::string &longprefix) const override; virtual void Reset() noexcept override;
#ifdef ARGS_NOEXCEPT
