            template <typename It> bool Complete(FlagBase &flag, It it, It end);
            template <typename It> std::string ParseArgsValues(FlagBase &flag, const std::string &arg, It &it, It end, const bool allowSeparate, const bool allowJoined, const bool hasJoined, const std::string &joinedArg, const bool canDiscardJoined, std::vector<std::string> &values);
            template <typename It> bool ParseLong(It &it, It end);
            template <typename It> bool ParseShort(It &it, It end);
            bool AddCompletionReply(const std::string &cur, const std::string &choice);
            template <typename It> bool Complete(It it, It end);
            template <typename It> It Parse(It begin, It end);
        public:
            HelpParams helpParams;
            ArgumentParser(const std::string &description_, const std::string &epilog_ = std::string());
            void AddCompletion(CompletionFlag &completionFlag);
            const std::string &Prog() const; void Prog(const std::string &prog_);
            const std::string &LongPrefix() const; void LongPrefix(const std::string &);
            const std::string &ShortPrefix() const; void ShortPrefix(const std::string &);
            const std::string &LongSeparator() const; void LongSeparator(const std::string &);
            const std::string &Terminator() const; void Terminator(const std::string &);
            void GetArgumentSeparations(bool &allowJoinedShortValue_, bool &allowJoinedLongValue_, bool &allowSeparateShortValue_, bool &allowSeparateLongValue_) const;
            void SetArgumentSeparations(const bool allowJoinedShortValue_, const bool allowJoinedLongValue_, const bool allowSeparateShortValue_, const bool allowSeparateLongValue_);
            void Help(std::ostream &help_) const; std::string Help() const; virtual void Reset() noexcept override;
            template <typename It> It ParseArgs(It begin, It end);
            template <typename T> auto ParseArgs(const T &args) -> decltype(std::begin(args));
            bool ParseCLI(const int argc, const char * const * argv);
            template <typename T> bool ParseCLI(const T &args);
    };

